        "question": "某理财产品名义年利率为 12%，按月复利计息（每年计息 12 次）。该理财产品的实际有效年利率（EAR）约为（ ）。（已知：$1.01^{12} \\approx 1.1268$）",
        "options": {
          "A": "12.00%",
          "B": "12.36%",
          "C": "12.68%",
          "D": "13.00%"
        },
        "answer": "C",
        "explanation": "【有效年利率（EAR）计算】\n① 核心公式：$EAR = (1 + \\frac{r}{m})^m - 1$\n② 代入数据：名义年利率 $r = 12\\%$，年计息次数 $m = 12$，月利率 $= 12\\% / 12 = 1\\% = 0.01$\n③ 逐步推导：$EAR = (1 + 0.01)^{12} - 1 = 1.1268 - 1 = 0.1268 = 12.68\\%$\n④ 结论对齐：有效年利率为 12.68%，故选 C。",
        "mnemonic": "有效利率看频次，名义除期复利滚。",
